#!/usr/bin/env bash
# Called only on a disposable backend runner, before any application tests.
set -euo pipefail
pg=(docker compose -f docker-compose.test.yml -p futureagi-test exec -T test-db)
tool=(python3 -I .ci/db_dump.py)
fresh="$RUNNER_TEMP/fresh-db"
stage="$RUNNER_TEMP/migrated-db"
mkdir -p "$fresh" "$stage"
if [[ $CACHE_HIT == true ]]; then
  bash "$(dirname "$0")/verify-record.sh" "$stage" "$RECIPE" >/dev/null
else
  # A partial or unexpected restore is not a clean staging directory.
  [[ -z $(find "$stage" -mindepth 1 -print -quit) ]]
fi
CI_PRESEED_DIGEST="$fresh/preseed" uv run pytest .ci/migrated_db.py --create-db -q
"${tool[@]}" dump "$fresh/internal.sql.gz" test_user test_tfc_test "${pg[@]}"
if [[ $CACHE_HIT == true && ! -f $stage/cold-only ]]; then
  "${tool[@]}" compare "$stage/dump.sql.gz" "$fresh/internal.sql.gz"
  cmp "$fresh/preseed" "$stage/preseed"
fi
# Compare the database at the input to post_migrate. Content types, permissions
# and UUID/timestamp-bearing templates are subsequently generated by real code.
"${pg[@]}" createdb -U test_user test_ci_roundtrip
"${tool[@]}" restore "$fresh/internal.sql.gz" test_user test_ci_roundtrip "${pg[@]}"
"${tool[@]}" seed-digest test_user test_ci_roundtrip "${pg[@]}" > "$fresh/before-reseed"
cold_only() {
  if [[ $CACHE_HIT == true && ! -f $stage/cold-only ]]; then
    echo 'A previously qualified cache no longer reconstructs a fresh database.' >&2
    exit 1
  fi
  printf '%s\n' "$RECIPE" > "$stage/cold-only"
  echo '::notice::Cold-only recipe; no SQL or application rows will be distributed.'
  exit 0
}
# A cold-only marker is a successful qualification result, not an error fallback.
for evidence in "$fresh/preseed" "$fresh/before-reseed"; do
  [[ $(wc -c < "$evidence") -eq 65 ]]
  LC_ALL=C grep -qxE '[0-9a-f]{64}' "$evidence"
done
cmp -s "$fresh/preseed" "$fresh/before-reseed" || {
  status=$?
  if [[ $status == 1 ]]; then cold_only; fi
  echo 'Could not compare seed digests.' >&2
  exit "$status"
}
CI_PRESEED_DIGEST="$fresh/replayed" PG_TEST_DB=test_ci_roundtrip uv run pytest .ci/migrated_db.py -q
cmp "$fresh/preseed" "$fresh/replayed"
if [[ $CACHE_HIT == true ]]; then exit 0; fi
# Public Actions artifacts/caches are not private storage. Only distribute SQL
# generated WITHOUT the private checkout. For a potentially eligible internal
# miss, compare against a public fresh database on this runner first. Never
# upload the private control dump (not even for diagnostics on failure).
public="$fresh/internal.sql.gz"
if [[ -e ee/cloud ]]; then
  mv ee/cloud "$RUNNER_TEMP/held-ee-checkout"
  trap 'mv "$RUNNER_TEMP/held-ee-checkout" ee/cloud' EXIT
  PG_TEST_DB=test_ci_public uv run pytest .ci/migrated_db.py --create-db -q
  public="$fresh/public.sql.gz"
  "${tool[@]}" dump "$public" test_user test_ci_public "${pg[@]}"
  # A difference is an unsupported class, not a reason to publish private SQL.
  "${tool[@]}" compare "$public" "$fresh/internal.sql.gz" > "$fresh/public-parity.log" || {
    status=$?
    # db_dump.COMPARE_DIFFERENT; every other nonzero status is a tool failure.
    if [[ $status == 3 ]]; then cold_only; fi
    echo 'Could not compare fresh database dumps.' >&2
    exit "$status"
  }
fi
cp "$public" "$stage/dump.sql.gz"
cp "$fresh/preseed" "$stage/preseed"
printf '%s\n' "$RECIPE" > "$stage/recipe"
(cd "$stage" && sha256sum dump.sql.gz preseed recipe > checksums)
